const exportCsv=(name:string,headers:string[],data:(string|number)[][])=>{const csv=[headers,...data].map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),link=document.createElement('a');link.href=url;link.download=name;link.click();URL.revokeObjectURL(url)}
function OldAnalyticsWorkspace({rows,municipalities,date,onClose,onSelect}:{rows:Forecast[];municipalities:MunicipalitySummary[];date:string;onClose:()=>void;onSelect:(row:Forecast)=>void}){const [tab,setTab]=useState<'overview'|'municipalities'|'barangays'|'alerts'>('overview'),alerts=rows.filter(row=>row.AUTOMATIC_OUTBREAK_ALERT),projected=rows.reduce((sum,row)=>sum+row.POSTERIOR_MEAN_CASES,0),download=()=>{if(tab==='municipalities')exportCsv(`oraclis-municipalities-${date}.csv`,['Municipality','Projected cases','Mean outbreak probability','Automatic alerts'],municipalities.map(row=>[row.MUNICIPALITY,row.POSTERIOR_MEAN_CASES,row.MEAN_OUTBREAK_PROBABILITY,row.AUTOMATIC_OUTBREAK_ALERT_COUNT]));else exportCsv(`oraclis-${tab}-${date}.csv`,['PSGC','Barangay','Municipality','Projected cases','Lower 95%','Upper 95%','Outbreak probability','Alert level','Hotspot score','Spatial lag'],(tab==='alerts'?alerts:rows).map(row=>[row.PSGC,row.BARANGAY,row.MUNICIPALITY,row.POSTERIOR_MEAN_CASES,row.LOWER_CREDIBLE_CASES,row.UPPER_CREDIBLE_CASES,row.OUTBREAK_PROBABILITY,row.ALERT_LEVEL,row.HOTSPOT_Z_SCORE,row.SPATIAL_LAG_CASES]))};return <div className="analytics-backdrop" role="presentation" onMouseDown={onClose}><section className="analytics-workspace" role="dialog" aria-modal="true" aria-labelledby="analytics-title" onMouseDown={event=>event.stopPropagation()}><header><div><span className="eyebrow">Province intelligence</span><h2 id="analytics-title">Analytics · {date}</h2></div><div><button className="export-data" onClick={download}>Export {tab} CSV</button><button className="modal-close" aria-label="Close analytics" onClick={onClose}>×</button></div></header><nav aria-label="Analytics sections">{(['overview','municipalities','barangays','alerts'] as const).map(item=><button key={item} className={tab===item?'active':''} onClick={()=>setTab(item)}>{item}</button>)}</nav>{tab==='overview'?<><div className="analytics-kpis"><div><span>Projected cases</span><strong>{projected.toFixed(1)}</strong></div><div><span>Barangays</span><strong>{rows.length}</strong></div><div><span>Automatic alerts</span><strong>{alerts.length}</strong></div><div><span>Municipalities</span><strong>{municipalities.length}</strong></div></div><div className="analytics-grid"><article><h3>Municipality projected cases</h3><ResponsiveContainer width="100%" height={300}><BarChart data={[...municipalities].sort((a,b)=>b.POSTERIOR_MEAN_CASES-a.POSTERIOR_MEAN_CASES)} layout="vertical"><XAxis type="number"/><YAxis dataKey="MUNICIPALITY" type="category" width={110} tick={{fontSize:10}}/><Tooltip/><Bar dataKey="POSTERIOR_MEAN_CASES" fill="#e5484d"/></BarChart></ResponsiveContainer></article><article><h3>Barangay risk distribution</h3><ResponsiveContainer width="100%" height={300}><BarChart data={['LOW','MODERATE','HIGH','CRITICAL'].map(level=>({level,count:rows.filter(row=>row.ALERT_LEVEL===level).length}))}><XAxis dataKey="level" tick={{fontSize:10}}/><YAxis/><Tooltip/><Bar dataKey="count" fill="#b98b42"/></BarChart></ResponsiveContainer></article></div></>:<div className="analytics-table-wrap"><table><thead><tr>{tab==='municipalities'?<><th>Municipality</th><th>Cases</th><th>Mean probability</th><th>Alerts</th></>:<><th>Barangay</th><th>Municipality</th><th>Cases</th><th>95% interval</th><th>Probability</th><th>Level</th><th>Hotspot</th></>}</tr></thead><tbody>{tab==='municipalities'?municipalities.map(row=><tr key={row.MUNICIPALITY}><td>{row.MUNICIPALITY}</td><td>{row.POSTERIOR_MEAN_CASES.toFixed(1)}</td><td>{Math.round(row.MEAN_OUTBREAK_PROBABILITY*100)}%</td><td>{row.AUTOMATIC_OUTBREAK_ALERT_COUNT}</td></tr>):(tab==='alerts'?alerts:rows).sort((a,b)=>b.POSTERIOR_MEAN_CASES-a.POSTERIOR_MEAN_CASES).map(row=><tr key={row.PSGC} onClick={()=>onSelect(row)}><td>{row.BARANGAY}</td><td>{row.MUNICIPALITY}</td><td>{row.POSTERIOR_MEAN_CASES.toFixed(1)}</td><td>{row.LOWER_CREDIBLE_CASES.toFixed(1)}–{row.UPPER_CREDIBLE_CASES.toFixed(1)}</td><td>{Math.round(row.OUTBREAK_PROBABILITY*100)}%</td><td>{row.ALERT_LEVEL}</td><td>{row.HOTSPOT_Z_SCORE.toFixed(2)}</td></tr>)}</tbody></table></div>}<footer>Scenario analytics—not official clinical surveillance.</footer></section></div>}
