type Forecast = { PSGC:string; BARANGAY:string; MUNICIPALITY:string; POSTERIOR_MEAN_CASES:number; LOWER_CREDIBLE_CASES:number; UPPER_CREDIBLE_CASES:number; OUTBREAK_PROBABILITY:number; HOTSPOT_Z_SCORE:number; SPATIAL_LAG_CASES:number; CASE_COLOR_INTENSITY:number; ALERT_LEVEL:string; RED_CLUSTER_SIZE:number; AUTOMATIC_OUTBREAK_ALERT:number; RED_CLUSTER_LIKELY_ORIGIN:number; DOMINANT_OUTBREAK_FACTOR:string }
type Collection<T> = { items:T[] }
type MunicipalitySummary = { MUNICIPALITY:string; POSTERIOR_MEAN_CASES:number; MEAN_OUTBREAK_PROBABILITY:number; AUTOMATIC_OUTBREAK_ALERT_COUNT:number }
type Cluster = { RED_CLUSTER_ID:number; CLUSTER_SIZE:number; PROJECTED_CASES:number; MAX_OUTBREAK_PROBABILITY:number; LIKELY_ORIGIN:string|null }
type Metric = 'probability'|'cases'|'upper'|'hotspot'|'spatial'
type WeatherForecast = { DATE:string; MUNICIPALITY:string; TEMPERATURE_MIN_C:number; TEMPERATURE_MAX_C:number; PRECIPITATION_MM:number; RAIN_PROBABILITY_PCT:number }
type LiveWeather = { MUNICIPALITY:string; OBSERVED_AT:string; TEMPERATURE_C:number; HUMIDITY_PCT:number; PRECIPITATION_MM:number; WIND_SPEED_KMH:number }
type WeatherScenario = { MUNICIPALITY:string; MUNICIPALITY_CODE:string; WEATHER_CONTEXT_MODIFIER:number; BASELINE_PROJECTED_CASES:number; WEATHER_CONTEXT_CASES:number; FORECAST_TEMPERATURE_C:number; FORECAST_RAINFALL_30D_EQUIVALENT_MM:number }
type ObservedAggregate = { psgc:string; reporting_period:string; total_cases:number; updated_at:string }
const labels:Record<Metric,string>={probability:'Outbreak probability',cases:'Projected cases',upper:'Upper credible cases',hotspot:'Hotspot score',spatial:'Neighbour spatial lag'}
const valueOf=(r:Forecast,m:Metric)=>m==='cases'?r.POSTERIOR_MEAN_CASES:m==='probability'?r.OUTBREAK_PROBABILITY:m==='upper'?r.UPPER_CREDIBLE_CASES:m==='hotspot'?r.HOTSPOT_Z_SCORE:r.SPATIAL_LAG_CASES
const municipalityKey=(value:string)=>value.toLowerCase().replace(/^city of\s+/,'').replace(/[^a-z0-9]/g,'')
const escapeHtml=(value:string)=>value.replace(/[&<>'"]/g,c=>({"&":'&amp;',"<":'&lt;',">":'&gt;',"'":'&#39;',"\"":'&quot;'}[c]!))
const centerOf=(geometry:unknown):[number,number]=>{const points:number[][]=[];const visit=(value:unknown):void=>{if(!Array.isArray(value))return;if(typeof value[0]==='number'&&typeof value[1]==='number')points.push(value as number[]);else value.forEach(visit)};visit((geometry as {coordinates?:unknown})?.coordinates);return points.length?[points.reduce((sum,p)=>sum+p[0],0)/points.length,points.reduce((sum,p)=>sum+p[1],0)/points.length]:[124.85,6.25]}

function MunicipalityReportChart({reports}:{reports:Array<ObservedAggregate&{barangay:string}>}){const total=reports.reduce((sum,item)=>sum+item.total_cases,0),data=[...reports].sort((a,b)=>b.total_cases-a.total_cases);return <section className="municipality-report-summary"><h3>Current barangay reports</h3><strong>{total}</strong><span>reported aggregate cases · {data.length} reporting barangay{data.length===1?'':'s'}</span>{data.length>0&&<ResponsiveContainer width="100%" height={Math.max(150,data.length*32)}><BarChart data={data} layout="vertical" margin={{left:6,right:18}}><XAxis type="number" allowDecimals={false} tick={{fill:'#a7afb5',fontSize:9}}/><YAxis dataKey="barangay" type="category" width={92} tick={{fill:'#dce5e8',fontSize:10}}/><Tooltip/><Bar dataKey="total_cases" name="Reported cases" fill="#e5484d" radius={[0,3,3,0]}/></BarChart></ResponsiveContainer>}</section>}

function ContextCharts({scenario,observed}:{scenario:WeatherScenario[];observed:ObservedAggregate[]}){const projections=[...scenario].map(row=>({name:row.MUNICIPALITY.replace('City of ',''),cases:row.WEATHER_CONTEXT_CASES,change:Math.round((row.WEATHER_CONTEXT_MODIFIER-1)*100)})).sort((a,b)=>b.cases-a.cases).slice(0,6),reports=[...observed].sort((a,b)=>b.total_cases-a.total_cases).slice(0,6).map(row=>({name:row.psgc.slice(-4),cases:row.total_cases}));return <section className="model-charts"><div className="section-heading"><span className="eyebrow">Dengue context</span><small>Next 16 days</small></div><h3>Weather-adjusted projected cases</h3><ResponsiveContainer width="100%" height={175}><BarChart data={projections} layout="vertical" margin={{left:4,right:12}}><XAxis type="number" tick={{fill:'#a7afb5',fontSize:9}}/><YAxis dataKey="name" type="category" width={88} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Bar dataKey="cases" name="Projected cases" fill="#f8c15b" radius={[0,3,3,0]}/></BarChart></ResponsiveContainer><h3>Current reported aggregate cases</h3><ResponsiveContainer width="100%" height={150}><BarChart data={reports} layout="vertical" margin={{left:4,right:12}}><XAxis type="number" allowDecimals={false} tick={{fill:'#a7afb5',fontSize:9}}/><YAxis dataKey="name" type="category" width={48} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Bar dataKey="cases" name="Reported cases" fill="#e5484d" radius={[0,3,3,0]}/></BarChart></ResponsiveContainer><p>Projection combines modeled dengue cases with municipality weather context.</p></section>}

function ModelCharts({timeline,municipalities,clusters}:{timeline:Forecast[];municipalities:MunicipalitySummary[];clusters:Cluster[]}){const municipalityData=[...municipalities].sort((a,b)=>b.POSTERIOR_MEAN_CASES-a.POSTERIOR_MEAN_CASES).slice(0,6).map(row=>({...row,name:row.MUNICIPALITY.replace('City of ','')}));return <section className="model-charts"><div className="section-heading"><span className="eyebrow">Model outputs</span><small>Scenario evidence</small></div><h3>Forecast and uncertainty</h3><ResponsiveContainer width="100%" height={150}><LineChart data={timeline}><CartesianGrid stroke="#353b40" vertical={false}/><XAxis dataKey="DATE" hide/><YAxis width={28} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Line type="monotone" dataKey="LOWER_CREDIBLE_CASES" stroke="#596168" dot={false}/><Line type="monotone" dataKey="POSTERIOR_MEAN_CASES" stroke="#e5484d" dot={false}/><Line type="monotone" dataKey="UPPER_CREDIBLE_CASES" stroke="#f5f1eb" dot={false}/></LineChart></ResponsiveContainer><h3>Municipality projected burden</h3><ResponsiveContainer width="100%" height={170}><BarChart data={municipalityData} layout="vertical" margin={{left:4}}><XAxis type="number" hide/><YAxis dataKey="name" type="category" width={78} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Bar dataKey="POSTERIOR_MEAN_CASES" fill="#e5484d" radius={[0,3,3,0]}/></BarChart></ResponsiveContainer>{clusters.length>0&&<><h3>Connected cluster impact</h3><ResponsiveContainer width="100%" height={130}><BarChart data={clusters}><XAxis dataKey="RED_CLUSTER_ID" tick={{fill:'#a7afb5',fontSize:9}}/><YAxis width={28} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Bar dataKey="PROJECTED_CASES" fill="#b98b42" radius={[3,3,0,0]}/></BarChart></ResponsiveContainer></>}<p>Scenario projections. Historical monthly values include interpolation.</p></section>}
function WeatherCharts({forecast,scenario,observed}:{forecast:WeatherForecast[];scenario:WeatherScenario[];observed:ObservedAggregate[]}){const daily=[...new Set(forecast.map(item=>item.DATE))].map(date=>{const rows=forecast.filter(item=>item.DATE===date);return {date:new Date(`${date}T00:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}),temperature:rows.reduce((sum,row)=>sum+(row.TEMPERATURE_MIN_C+row.TEMPERATURE_MAX_C)/2,0)/Math.max(rows.length,1),rain:rows.reduce((sum,row)=>sum+row.PRECIPITATION_MM,0)/Math.max(rows.length,1)}}),risk=scenario.map(item=>({name:item.MUNICIPALITY.replace('City of ',''),change:Math.round((item.WEATHER_CONTEXT_MODIFIER-1)*100)})).sort((a,b)=>b.change-a.change).slice(0,6),cases=[...observed].sort((a,b)=>b.total_cases-a.total_cases).slice(0,6).map(item=>({name:item.psgc.slice(-4),cases:item.total_cases}));return <section className="model-charts"><div className="section-heading"><span className="eyebrow">Dengue and weather</span><small>16-day outlook</small></div><h3>Temperature outlook</h3><ResponsiveContainer width="100%" height={150}><LineChart data={daily}><CartesianGrid stroke="#353b40" vertical={false}/><XAxis dataKey="date" hide/><YAxis width={28} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Line type="monotone" dataKey="temperature" name="Mean temperature °C" stroke="#f8c15b" dot={false}/></LineChart></ResponsiveContainer><h3>Reported cases by barangay</h3><ResponsiveContainer width="100%" height={150}><BarChart data={cases} layout="vertical" margin={{left:4}}><XAxis type="number" tick={{fill:'#a7afb5',fontSize:9}}/><YAxis dataKey="name" type="category" width={48} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Bar dataKey="cases" name="Reported cases" fill="#e5484d" radius={[0,3,3,0]}/></BarChart></ResponsiveContainer><h3>Municipality weather context</h3><ResponsiveContainer width="100%" height={130}><BarChart data={risk} layout="vertical" margin={{left:4}}><XAxis type="number" tick={{fill:'#a7afb5',fontSize:9}}/><YAxis dataKey="name" type="category" width={78} tick={{fill:'#a7afb5',fontSize:9}}/><Tooltip/><Bar dataKey="change" name="Weather context %" fill="#75b8ff" radius={[0,3,3,0]}/></BarChart></ResponsiveContainer><p>Reported totals, model risk, and weather context stay separate.</p></section>}
function RainIcon(){return <svg className="weather-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 18a4 4 0 1 1 .7-7.94A5.5 5.5 0 0 1 18 12.5 3.5 3.5 0 0 1 17.5 19H7Z"/><path d="m9 21 .6-1.5M13 21l.6-1.5M17 21l.6-1.5"/></svg>}
const rainStreak=(items:WeatherForecast[])=>items.reduce((state,item)=>{const wet=(item.PRECIPITATION_MM??0)>=5||(item.RAIN_PROBABILITY_PCT??0)>=70;return wet?{run:state.run+1,max:Math.max(state.max,state.run+1)}:{run:0,max:state.max}},{run:0,max:0}).max
function WeatherModal({municipality,scenario,live,forecast,loading,onClose}:{municipality:string;scenario?:WeatherScenario;live?:LiveWeather;forecast:WeatherForecast[];loading:boolean;onClose:()=>void}){const [days,setDays]=useState<7|16>(7),items=forecast.filter(item=>municipalityKey(item.MUNICIPALITY)===municipalityKey(municipality)).slice(0,days),rain=Math.max(0,...items.map(item=>item.RAIN_PROBABILITY_PCT??0)),total=items.reduce((sum,item)=>sum+(item.PRECIPITATION_MM??0),0),heat=Math.max(0,...items.map(item=>item.TEMPERATURE_MAX_C??0)),change=scenario?Math.round((scenario.WEATHER_CONTEXT_MODIFIER-1)*100):Math.round(Math.min(15,Math.max(-15,(rain-60)/8+(total-30)/12+(heat-31)*2))),level=change>=8?'Elevated':change<=-8?'Lower':'Watch',chart=items.map(item=>({...item,label:new Date(`${item.DATE}T00:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'}),TEMPERATURE_C:(item.TEMPERATURE_MIN_C+item.TEMPERATURE_MAX_C)/2})),streak=rainStreak(items);return <div className="barangay-modal-backdrop" role="presentation" onMouseDown={onClose}><section className="barangay-modal weather-modal" role="dialog" aria-modal="true" aria-labelledby="weather-modal-title" onMouseDown={event=>event.stopPropagation()}><button className="modal-close" aria-label="Close municipality weather" onClick={onClose}>×</button><span className="eyebrow">Municipality weather outlook</span><h2 id="weather-modal-title">{municipality}</h2>{loading?<div className="weather-loader"><div className="weather-orbit"><i/><i/><i/></div><strong>ASSESSING ATMOSPHERIC SIGNALS</strong><span>Synchronizing current conditions</span><span>Applying rainfall and heat indices</span><span>Calculating municipal weather risk</span><b>ORACLIS CLIMATE ENGINE</b></div>:<><div className="modal-stat"><strong>{level}</strong><span>current weather risk level</span></div>{streak>=3&&<div className="rain-alert" role="alert"><strong>Continuous rainfall detected</strong><span>{streak} consecutive forecast days show substantial rain.</span><button onClick={()=>window.dispatchEvent(new CustomEvent('oraclis:weather-alert',{detail:{municipality,wetDays:streak,forecast:items}}))}>Send email &amp; SMS alert</button></div>}<dl><div><dt>Current temperature</dt><dd>{live?`${live.TEMPERATURE_C.toFixed(1)}°C`:'Unavailable'}</dd></div><div><dt>Humidity</dt><dd>{live?`${live.HUMIDITY_PCT}%`:'Unavailable'}</dd></div><div><dt>Rain now</dt><dd>{live?`${live.PRECIPITATION_MM.toFixed(1)} mm`:'Unavailable'}</dd></div><div><dt>Wind</dt><dd>{live?`${live.WIND_SPEED_KMH.toFixed(1)} km/h`:'Unavailable'}</dd></div></dl><div className="weather-range"><button className={days===7?'active':''} onClick={()=>setDays(7)}>7 days</button><button className={days===16?'active':''} onClick={()=>setDays(16)}>16 days</button></div><h3>Climate change · next {days} days</h3>{chart.length?<ResponsiveContainer width="100%" height={210}><LineChart data={chart}><CartesianGrid stroke="#353b40" vertical={false}/><XAxis dataKey="label" tick={{fill:'#a7afb5',fontSize:9}}/><YAxis yAxisId="temp" width={30} tick={{fill:'#a7afb5',fontSize:9}}/><YAxis yAxisId="rain" orientation="right" width={30} tick={{fill:'#75b8ff',fontSize:9}}/><Tooltip/><Line yAxisId="temp" type="monotone" dataKey="TEMPERATURE_C" name="Mean temperature °C" stroke="#f8c15b" strokeWidth={2} dot={false}/><Bar yAxisId="rain" dataKey="PRECIPITATION_MM" name="Rainfall mm" fill="#75b8ff"/></LineChart></ResponsiveContainer>:<p className="modal-note">Forecast unavailable.</p>}<p className="modal-note">{change>0?'+':''}{change}% weather context. Weather signal only; not dengue probability.</p></>}</section></div>}
let alertMap:MapLibreMap|null=null
const captureAlertMap=async()=>{if(!alertMap)throw new Error('Map is not ready for capture.');await new Promise<void>(resolve=>{alertMap!.once('render',()=>resolve());alertMap!.triggerRepaint()});const source=alertMap.getCanvas(),canvas=document.createElement('canvas'),context=canvas.getContext('2d',{willReadFrequently:true});canvas.width=source.width;canvas.height=source.height;if(!context)throw new Error('Map capture is unavailable.');context.drawImage(source,0,0);const pixels=context.getImageData(0,0,canvas.width,canvas.height).data;let visible=0;for(let i=0;i<pixels.length;i+=1600)if(pixels[i]+pixels[i+1]+pixels[i+2]>24)visible++;if(visible<10)throw new Error('Map has not finished rendering. Wait a moment and try again.');return canvas.toDataURL('image/jpeg',.9)}
const postWeatherAlert=(event:Event)=>{const detail=(event as CustomEvent<{municipality:string;wetDays:number}>).detail;if(!detail?.municipality)return;const dialog=document.createElement('dialog');dialog.className='alert-send-modal';dialog.innerHTML=`<form method="dialog"><span class="eyebrow">Public warning workflow</span><h2>Send dengue risk alert?</h2><p>This creates a combined risk-map and rainfall-chart post for the connected Facebook Page.</p><dl><div><dt>Municipality</dt><dd>${detail.municipality}</dd></div><div><dt>Detected wet streak</dt><dd>${detail.wetDays} days</dd></div></dl><aside><strong>Before publishing</strong><span>Current map view gets captured and forecast gets checked again by server. Readers receive dengue prevention guidance and are directed to LGU and PAGASA advisories.</span></aside><output aria-live="polite"></output><footer><button value="cancel">Cancel</button><button type="button" class="send">Send Facebook alert</button></footer></form>`;document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove());dialog.querySelector<HTMLButtonElement>('.send')!.onclick=async()=>{const send=dialog.querySelector<HTMLButtonElement>('.send')!,output=dialog.querySelector('output')!;send.disabled=true;send.innerHTML='<i></i> Building map and chart…';output.textContent='Capturing current map and validating forecast…';try{const response=await fetch('/api/weather/facebook-post',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({municipality:detail.municipality,map_image:await captureAlertMap()})}),payload=await response.json();if(!response.ok)throw new Error(payload.message??`Post failed (${response.status})`);output.className='success';output.textContent='Combined alert card sent to Facebook.';send.textContent='Done';send.onclick=()=>dialog.close()}catch(error){output.className='error';output.textContent=error instanceof Error?error.message:'Facebook alert failed.';send.disabled=false;send.textContent='Try again'}};dialog.showModal()}
window.addEventListener('oraclis:weather-alert',postWeatherAlert)
function WeatherCards({items,onClose}:{items:WeatherForecast[];onClose:()=>void}){const dates=[...new Set(items.map(item=>item.DATE))],places=[...new Set(items.map(item=>item.MUNICIPALITY))];return <section className="weather-cards" aria-label="16-day Open-Meteo forecast"><header><div><span className="eyebrow">Live weather outlook</span><h2>Next 16 days</h2><p>Open-Meteo forecast · weather context only</p></div><button onClick={onClose} aria-label="Close weather forecast">×</button></header><div className="weather-grid">{dates.map(day=>{const daily=items.filter(item=>item.DATE===day),rain=Math.max(...daily.map(item=>item.RAIN_PROBABILITY_PCT??0)),low=Math.min(...daily.map(item=>item.TEMPERATURE_MIN_C)),high=Math.max(...daily.map(item=>item.TEMPERATURE_MAX_C));return <article key={day}><time>{new Date(`${day}T00:00:00`).toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</time><strong>{Math.round(low)}–{Math.round(high)}°</strong><span><RainIcon/>{Math.round(rain)}%</span><small>{daily.reduce((sum,item)=>sum+(item.PRECIPITATION_MM??0),0).toFixed(1)} mm · {places.length} municipalities</small></article>})}</div></section>}
